sc=[j for j in range(W) if len({ti[i][j] for i in range(H)})==1]
vr=[];prev=-1
for e in sorted(sr)+[H]:
    if e-prev>1: vr.append((prev+1,e-1)); prev=e
vc=[];prev=-1
for e in sorted(sc)+[W]:
    if e-prev>1: vc.append((prev+1,e-1)); prev=e
# 5-pairs per block, with exact positions relative to block
for k,(a,b) in enumerate(vr):
    for m,(c,d) in enumerate(vc):
        fives=[(i-a,j-c) for i in range(a,b+1) for j in range(c,d+1) if ti[i][j]==5]
        # orthogonal adjacency within block
        adj=set()
        for (ri,rj) in fives:
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                if (ri+dx,rj+dy) in set(fives): adj.add((ri,rj))
        print(k,m,'fives',fives,'adj count',len(adj))
